msg.headers = { "Content-Type": "text/plain; charset=utf-8" };
msg.payload = "Привет! Это лабораторная №2 по Node-RED. Студент: Дусов, группа СПД ИИ-241.";
return msg;

msg.payload = {
    student: "Дусов",
    serverTime: new Date().toISOString()
};
return msg;

// GET /api/items        — список, query: ?category=<строка>&limit=<1..10>
// GET /api/items/:id    — один материал по id
const items = [
    { id: 1, name: "Кирпич керамический М150", category: "brick",  price: 420 },
    { id: 2, name: "Цемент М500 Д0",           category: "cement", price: 18 },
    { id: 3, name: "ГКЛ Стандарт 12.5 мм",     category: "gypsum", price: 9 },
    { id: 4, name: "Минеральная вата Лайт",    category: "insulation", price: 35 },
    { id: 5, name: "Кирпич силикатный М100",   category: "brick",  price: 310 }
];

function reply(status, body) {
    msg.statusCode = status;
    msg.headers = { "Content-Type": "application/json; charset=utf-8" };
    msg.payload = body;
    return msg;
}

const params = msg.req.params || {};
const query = msg.req.query || {};

// --- /api/items/:id ---
if (params.id !== undefined) {
    if (!/^\d+$/.test(params.id)) {
        return reply(400, { error: "id должен быть положительным целым числом", got: params.id });
    }
    const item = items.find(x => x.id === Number(params.id));
    if (!item) {
        return reply(404, { error: "Материал не найден", id: Number(params.id) });
    }
    return reply(200, item);
}

// --- /api/items?category=&limit= ---
let result = items;
if (query.category !== undefined) {
    result = result.filter(x => x.category === query.category);
    if (result.length === 0) {
        return reply(404, { error: "Нет материалов в категории", category: query.category });
    }
}
if (query.limit !== undefined) {
    const limit = Number(query.limit);
    if (!Number.isInteger(limit) || limit < 1 || limit > 10) {
        return reply(400, { error: "limit должен быть целым числом от 1 до 10", got: query.limit });
    }
    result = result.slice(0, limit);
}
return reply(200, { student: "Дусов", count: result.length, items: result });
